#define CROW_HIP_ROLL_LIBRARY
#include "../crow-v15-hip-roll-strong-drive-prototype-20261111/probe.cpp"
#import <Foundation/Foundation.h>
#import <Metal/Metal.h>
#include <iomanip>
struct Sample{unsigned arm,lane,step;std::vector<float>q,v;};
int main(int argc,char**argv){@autoreleasepool{try{
 need(argc==2,"metallib argument required");RunManifest m;m.id="aero_eval";m.robot=hipRollModel();m.scene=makeBirdFlowAmericanCrowFlightScenePack();m.sensors.id="proprioception";m.task=makeAmericanCrowEmbodiedTaskPack(m.sensors.observation,m.reality.reset);m.reality.reset={};m.reality.id="reality";m.teacher.id="no_teacher";m.profile.id="probe";m.profile.capacities={.candidatePairs=512,.rawContacts=2048,.manifolds=512,.constraintBlocks=2048,.constraintRows=6144};m.task.capacities=m.profile.capacities;m.profile.environmentCount=1;m.profile.controlSteps=1;m.profile.physicsSubsteps=16;m.profile.controlTimestepSeconds=.02f;
 CompiledRun run;auto status=compileRun(m,run);need(status.succeeded(),"compileRun: "+status.message);auto p=run.flappingWingProgram();need(p&&p->valid(),"invalid aero program");auto& model=run.model();const unsigned nq=model.defaultQ.size(),nv=model.defaultV.size(),nb=model.bodies.size();std::vector<Sample>s;unsigned arm,lane,step;
 while(std::cin>>arm>>lane>>step){Sample x{arm,lane,step,std::vector<float>(nq),std::vector<float>(nv)};for(auto&v:x.q)need(bool(std::cin>>v),"missing q");for(auto&v:x.v)need(bool(std::cin>>v),"missing v");s.push_back(std::move(x));}need(!s.empty(),"no samples");
 std::vector<float>q,v;for(const auto&x:s){q.insert(q.end(),x.q.begin(),x.q.end());v.insert(v.end(),x.v.begin(),x.v.end());}std::vector<MRABABodyWrenchGPU>w(s.size()*nb);
 MRCompiledFlappingWingDispatchGPU d{};d.environmentCount=s.size();d.qStride=nq;d.vStride=nv;d.bodyStride=nb;d.rootBodyIndex=p->rootBodyIndex;d.windVelocityAndDensity=p->windVelocityAndDensity;
 id<MTLDevice> device=MTLCreateSystemDefaultDevice();need(device!=nil,"no metal device");NSError*error=nil;id<MTLLibrary>lib=[device newLibraryWithFile:[NSString stringWithUTF8String:argv[1]] error:&error];need(lib!=nil,"load metallib");id<MTLFunction>fn=[lib newFunctionWithName:@"mr_step_compiled_flapping_wings"];need(fn!=nil,"missing kernel");id<MTLComputePipelineState>pipeline=[device newComputePipelineStateWithFunction:fn error:&error];need(pipeline!=nil,"pipeline");id<MTLCommandQueue>queue=[device newCommandQueue];
 auto buffer=[&](const void*ptr,NSUInteger n){return [device newBufferWithBytes:ptr length:n options:MTLResourceStorageModeShared];};id<MTLBuffer>buf[7]={buffer(p->wings.data(),sizeof(MRFlappingWingGPU)*2),buffer(&d,sizeof(d)),buffer(q.data(),q.size()*sizeof(float)),buffer(v.data(),v.size()*sizeof(float)),buffer(w.data(),w.size()*sizeof(w[0])),buffer(&p->tail,sizeof(p->tail)),buffer(&p->fuselage,sizeof(p->fuselage))};for(auto b:buf)need(b!=nil,"buffer failed");
 id<MTLCommandBuffer>cb=[queue commandBuffer];id<MTLComputeCommandEncoder>enc=[cb computeCommandEncoder];[enc setComputePipelineState:pipeline];for(unsigned i=0;i<7;i++)[enc setBuffer:buf[i] offset:0 atIndex:i];[enc dispatchThreads:MTLSizeMake(s.size(),1,1) threadsPerThreadgroup:MTLSizeMake(std::min<NSUInteger>(64,pipeline.maxTotalThreadsPerThreadgroup),1,1)];[enc endEncoding];[cb commit];[cb waitUntilCompleted];need(cb.status==MTLCommandBufferStatusCompleted,"gpu kernel error");auto out=(const MRABABodyWrenchGPU*)[buf[4] contents];
 std::cerr<<"robot_fingerprint "<<run.robotFingerprint()<<"\n";std::cerr<<"samples "<<s.size()<<" nq "<<nq<<" nv "<<nv<<" bodies "<<nb<<" root "<<p->rootBodyIndex<<" wings "<<p->wings[0].bodyIndex<<" "<<p->wings[1].bodyIndex<<" zcoef "<<p->wings[0].unsteadyCoefficients.z<<" "<<p->wings[1].unsteadyCoefficients.z<<"\n";
 std::cout<<std::setprecision(10);for(unsigned i=0;i<s.size();i++){const auto&x=s[i];std::vector<double>qd(x.q.begin(),x.q.end()),vd(x.v.begin(),x.v.end());std::vector<ArticulatedBodyKinematics>k(model.articulations[0].bodyCount);auto kin=computeArticulatedBodyKinematics(model,0,qd,vd,k);need(kin.succeeded(),"FK failed");std::cout<<x.arm<<" "<<x.lane<<" "<<x.step;for(unsigned side=0;side<2;side++){unsigned b=p->wings[side].bodyIndex;const auto&z=out[i*nb+b];auto pos=k[b].centerOfMassPosition;double rx=pos[0]-x.q[0],ry=pos[1]-x.q[1];double mz=z.torque.z+rx*z.force.y-ry*z.force.x;std::cout<<" "<<z.force.x<<" "<<z.force.y<<" "<<z.force.z<<" "<<mz;}const auto&root=out[i*nb+p->rootBodyIndex];std::cout<<" "<<root.torque.z<<"\n";}
 return 0;}catch(const std::exception&e){std::cerr<<"error "<<e.what()<<"\n";return 1;}}}
